def render_position(pos):
    walls = pos['walls']
    boxes = pos['boxes']
    targets = pos['targets']
    player = pos['player']
    rows = pos['rows']
    cols = pos['cols']
    out = []
    for r in range(rows):
        line = []
        for c in range(cols):
            cell = (r, c)
            if cell in walls:
                line.append('#')
            elif cell == player:
                line.append('+' if cell in targets else '@')
            elif cell in boxes:
                line.append('*' if cell in targets else '$')
            elif cell in targets:
                line.append('.')
            else:
                line.append(' ')
        out.append(''.join(line))
    return '\n'.join(out)
